postmortem.raw:
{
  "root_cause": "Ambiguous instruction to Runner without safeguards, causing it to delete live customer records.",
  "contributing": [
    "Test records were not uniquely tagged separate from production data.",
    "No pre‑execution validation or dry‑run step before destructive commands.",
    "No approval or peer‑review process for DELETE operations on critical tables.",
    "Runner is configured to execute commands without safety checks or confirmations."
  ],
  "who_is_accountable": "Operations Lead (the person who issued the delete command).",
  "actions": [
    {
      "change": "Introduce a mandatory tagging scheme for test vs. production records.",
      "so_that": "Test data can be isolated and excluded from bulk operations."
    },
    {
      "change": "Implement a two‑step approval workflow for any DELETE/UPDATE on the customer table.",
      "so_that": "Human review prevents accidental mass deletions."
    },
    {
      "change": "Add a dry‑run / preview mode to Runner that reports affected row count before execution.",
      "so_that": "Operators can verify scope before committing."
    },
    {
      "change": "Require an explicit \"--confirm\" flag for destructive commands in Runner.",
      "so_that": "Accidental runs are blocked."
    },
    {
      "change": "Log all destructive SQL statements and trigger alerts for large row counts.",
      "so_that": "Auditing catches anomalies early."
    },
    {
      "change": "Update documentation and train staff on safe data‑operation procedures.",
      "so_that": "Everyone understands the new safeguards."
    }
  ],
  "what_i_tell_a4": "From now on, only execute DELETE statements on the customer table after a dry‑run that returns the row count and after receiving an explicit \"--confirm\" flag. If either step is missing, abort the operation and raise an alert."
}
